import {getAction,getCharacter} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const substitutePhysicalScenarios=['substitute-one','substitute-multi','substitute-followers','substitute-receiver-followers','substitute-counter','substitute-mental','substitute-water','substitute-near','substitute-canceled','substitute-third','substitute-refill','substitute-decline','substitute-teleport','substitute-reaction','substitute-chain'] as const;
export type SubstitutePhysicalScenario=typeof substitutePhysicalScenarios[number];
export function isSubstitutePhysicalScenario(name:string):name is SubstitutePhysicalScenario{return (substitutePhysicalScenarios as readonly string[]).includes(name);}
export function substituteMode(name:SubstitutePhysicalScenario){const multi=['substitute-multi','substitute-followers','substitute-receiver-followers','substitute-chain'].includes(name),follower=name==='substitute-followers'||name==='substitute-receiver-followers';return {multi,follower,receiver:name==='substitute-receiver-followers',hit:multi?1:0,attack:multi?'a2-p10-r1c3':name==='substitute-water'?'a2-p12-r2c2':name==='substitute-near'?'a2-p24-r1c3':'a2-p24-r1c2',ability:name==='substitute-mental'?'c2-p03-r2c1-ab01':name==='substitute-water'?'c2-p04-r1c1-ab01':null};}
/** Initial deal/training only; actual follower placement, CHANT, prior turns, reveal and APPROACH produce prerequisites. */
export function makeSubstitutePhysicalScenario(name:SubstitutePhysicalScenario,players:{id:string;name:string}[]){
 const m=substituteMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.multi?'侍大将のシン':'魔導王ガイナス',m.multi?'黒騎士ガーウィン':'聖騎士ランスロット',name==='substitute-mental'?getCharacter('c2-p03-r2c1')!.name:name==='substitute-water'?getCharacter('c2-p04-r1c1')!.name:name==='substitute-chain'?'黒妖精のアーネス':'忍びのイダ',name==='substitute-chain'?getCharacter('c2-p05-r1c2')!.name:'大神官ジル'][i]!);for(const p of Object.values(s.players))p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:2};
 const keep=[takeCard(s,a,m.attack),takeCard(s,c,'a2-p02-r2c1'),takeCard(s,c,name==='substitute-reaction'?'a2-p02-r2c3':name==='substitute-teleport'?'a2-p06-r1c1':'a2-p05-r3c1'),takeCard(s,c,'a2-p07-r1c1'),takeCard(s,c,'a2-p10-r3c3'),...(name==='substitute-reaction'?[]:[takeCard(s,d,'a2-p02-r2c3')]),takeCard(s,d,'a2-p01-r2c3')];const wood=m.follower?takeCard(s,b,'ウッドゴーレム'):undefined,metal=m.receiver?takeCard(s,c,'メタルゴーレム'):undefined;if(wood)keep.push(wood);if(metal)keep.push(metal);if(name==='substitute-near')keep.push(takeCard(s,a,'a2-p24-r1c2'));for(const p of players)trimHand(s,p.id,...keep);
 let blood:string|undefined;if(name==='substitute-refill'){blood=takeCard(s,a,'a2-p01-r1c3');s.players[a]!.hand=s.players[a]!.hand.filter(id=>id!==blood);}const ordinary=s.deck.filter(id=>getAction(id)!.category!=='open'),opens=s.deck.filter(id=>getAction(id)!.category==='open');s.deck=blood?[blood,...ordinary,...opens]:[...ordinary,...opens];s.events=[];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e=entropy(),r=transition(s,input,e);if(!r.ok)throw Error(`SUBSTITUTE_PHYSICAL_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('SUBSTITUTE_PHYSICAL_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('SUBSTITUTE_PHYSICAL_CARDS');}
 function settle(){for(let n=0;n<300;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('SUBSTITUTE_PHYSICAL_WINDOW');}
 function start(id:string){act(id,{type:'START_TURN'});settle();act(id,{type:'CHOOSE_DRAW',draw:false});settle();}
 function end(id:string){if(s.phase==='action')act(id,{type:'PASS_ACTION'});if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.filter(x=>!keep.includes(x)).slice(0,Math.max(0,s.players[id]!.hand.length-gameStats(s,id).handLimit))});settle();}
 for(const id of [a,b,c,d]){if(id===b&&wood)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:wood});if(id===c&&metal)act(id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:metal});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));start(a);if(name==='substitute-third'){act(a,{type:'REVEAL_CHARACTER'});settle();}if(m.multi){act(a,{type:'CHANT',cardInstanceId:m.attack});end(a);for(const id of [b,c,d]){start(id);end(id);}start(a);}if(name==='substitute-near'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c2',targetId:b});settle();}if(blood&&s.deck[0]!==blood)throw Error('SUBSTITUTE_PHYSICAL_BLOOD');return s;
}
